export function distanceKm(a,b){const r=Math.PI/180,h=Math.sin((b.latitude-a.latitude)*r/2)**2+Math.cos(a.latitude*r)*Math.cos(b.latitude*r)*Math.sin((b.longitude-a.longitude)*r/2)**2;return 6371*2*Math.asin(Math.sqrt(Math.min(1,h)))}
export const distanceText=km=>km<1?Math.round(km*1000/50)*50+' m':km.toLocaleString('it-IT',{maximumFractionDigits:1})+' km';
export function rankShelters(places,origin,type='all',radius=5){return places.map(p=>({...p,latitude:p.lat,longitude:p.lon,distance:distanceKm(origin,{latitude:p.lat,longitude:p.lon})})).filter(p=>Number.isFinite(p.distance)&&p.distance<=radius&&(type==='all'||p.type===type)).sort((a,b)=>a.distance-b.distance)}
export function directionsURL(p,type='car'){return 'https://www.google.com/maps/dir/?'+new URLSearchParams({api:'1',destination:p.latitude+','+p.longitude,travelmode:type==='people'?'walking':'driving'})}
export function rainWindow(weather){const h=weather?.hourly,c=weather?.current;if(!h?.time||!c?.time)return null;const index=h.time.findIndex(t=>t>c.time);if(index<0)return null;for(let i=index;i<Math.min(index+12,h.time.length);i++){const mm=h.precipitation?.[i],chance=h.precipitation_probability?.[i];if(Number.isFinite(mm)&&mm>=.1&&Number.isFinite(chance)&&chance>=40)return {time:h.time[i],probability:chance,mm}}return null}
export function radarPoint(x,y,z=7){const size=256*2**z;return {longitude:x/size*360-180,latitude:Math.atan(Math.sinh(Math.PI*(1-2*y/size)))*180/Math.PI}}
export function radarPixel(p,z=7){const size=256*2**z,sin=Math.sin(p.latitude*Math.PI/180);return {x:(p.longitude+180)/360*size,y:(.5-Math.log((1+sin)/(1-sin))/(4*Math.PI))*size}}
// Returns proximity to a colored echo, not a storm track, rain rate or hail detection.
export function scanRadarTiles(tiles,origin,radius=50,z=7){let nearest=null,total=0,covered=0;const pixel=radarPixel(origin,z),range=radius*1.3/(40075*Math.cos(origin.latitude*Math.PI/180)/(256*2**z));for(const t of tiles){const {data,width}=t.radar,mask=t.coverage.data;for(let y=Math.max(0,Math.floor(pixel.y-range-t.y*256));y<Math.min(width,Math.ceil(pixel.y+range-t.y*256));y++)for(let x=Math.max(0,Math.floor(pixel.x-range-t.x*256));x<Math.min(width,Math.ceil(pixel.x+range-t.x*256));x++){const point=radarPoint(t.x*256+x+.5,t.y*256+y+.5,z),km=distanceKm(origin,point);if(km>radius)continue;total++;const i=(y*width+x)*4;if(mask[i+3]>20)continue;covered++;if(data[i+3]<240)continue;if(!nearest||km<nearest.km)nearest={...point,km}}}return {nearest,coverage:total?covered/total:0,radius,resolutionKm:40075*Math.cos(origin.latitude*Math.PI/180)/(256*2**z)}}
